CREATE TABLE public.estoque_conferencia_fechamentos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), data_conferencia date NOT NULL, data_contagem date NOT NULL, momento text NOT NULL CHECK (momento IN ('inicio','fim')), unidade_id uuid NOT NULL REFERENCES public.unidades(id), empresa_id uuid NOT NULL REFERENCES public.empresas(id), produto_grupo text NOT NULL CHECK (produto_grupo IN ('P13','P20','P45','Agua')), tipo_estoque text NOT NULL CHECK (tipo_estoque IN ('cheio','vazio')), quantidade integer NOT NULL CHECK (quantidade >= 0), conferido_por uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(data_conferencia,unidade_id,produto_grupo,tipo_estoque), CHECK (data_conferencia = (CASE WHEN momento='inicio' THEN data_contagem-1 ELSE data_contagem END))
);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.estoque_conferencia_fechamentos TO authenticated;
GRANT ALL ON public.estoque_conferencia_fechamentos TO service_role;
ALTER TABLE public.estoque_conferencia_fechamentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY conferencia_fechamentos_read ON public.estoque_conferencia_fechamentos FOR SELECT TO authenticated USING (public.unidade_belongs_to_user_empresa(unidade_id) AND empresa_id=public.get_user_empresa_id());
CREATE POLICY conferencia_fechamentos_insert ON public.estoque_conferencia_fechamentos FOR INSERT TO authenticated WITH CHECK (public.unidade_belongs_to_user_empresa(unidade_id) AND empresa_id=public.get_user_empresa_id() AND EXISTS (SELECT 1 FROM public.unidades u WHERE u.id=estoque_conferencia_fechamentos.unidade_id AND u.empresa_id=estoque_conferencia_fechamentos.empresa_id));
CREATE POLICY conferencia_fechamentos_update ON public.estoque_conferencia_fechamentos FOR UPDATE TO authenticated USING (public.unidade_belongs_to_user_empresa(unidade_id) AND empresa_id=public.get_user_empresa_id()) WITH CHECK (public.unidade_belongs_to_user_empresa(unidade_id) AND empresa_id=public.get_user_empresa_id() AND EXISTS (SELECT 1 FROM public.unidades u WHERE u.id=estoque_conferencia_fechamentos.unidade_id AND u.empresa_id=estoque_conferencia_fechamentos.empresa_id));
CREATE POLICY conferencia_fechamentos_delete ON public.estoque_conferencia_fechamentos FOR DELETE TO authenticated USING (public.unidade_belongs_to_user_empresa(unidade_id) AND empresa_id=public.get_user_empresa_id());